  if (!file.is_open()) {
    return;
  }
  std::ofstream output_file("temp_salesmen.txt", std::ios::out);
  std::string line;
  while (std::getline(file, line)) {
    std::istringstream iss(line);
    std::string code;
    iss >> code;
    if (code != salesman_code) {
      output_file << line << std::endl;
